--
-- Table structure for table `car_sales`
--

DROP TABLE IF EXISTS `car_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `car_sales` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ranking` int NOT NULL COMMENT '排名',
  `car_name` varchar(50) NOT NULL COMMENT '车名',
  `sales` int NOT NULL COMMENT '销量',
  `month` char(2) NOT NULL COMMENT '月份(01-12)',
